  function jobsView(vs,cs) {var filtered=vs.filter(function(v){return (!expiringOnly||isEnding(v))&&(!visibilityFilter||hasVisibility(v,visibilityFilter))&&(statusFilter==='all'||jobStatus(v)===statusFilter)&&(!locationFilter||jobLocation(v)===locationFilter)&&(!areaFilter||String(v.area||'').trim()===areaFilter)&&norm((v.cargo||v.titulo||'')+' '+(v.cidade||'')+' '+v.id).indexOf(norm(query))>=0;});filtered.sort(compareJobs);var size=8,total=Math.max(1,Math.ceil(filtered.length/size));pageNumber=Math.min(pageNumber,total);return '<section class="card section jobs-reference">'+intro('Minhas vagas','Acompanhe suas vagas e gerencie os candidatos.',publish())+'<div class="filters"><div class="job-tabs" aria-label="Filtrar por status">'+[['all','Todas'],['active','Ativas'],['pending','Em análise'],['paused','Pausadas'],['closed','Encerradas']].map(function(x){return '<button class="'+(statusFilter===x[0]?'selected':'')+'" data-action="job-filter" data-filter="'+x[0]+'" aria-pressed="'+(statusFilter===x[0])+'">'+x[1]+' <span class="tab-count">'+vs.filter(function(v){return x[0]==='all'||jobStatus(v)===x[0];}).length+'</span></button>';}).join('')+'</div>'+visibilityCards(vs)+'</div>'+(visibilityFilter?'<div class="visibility-filter-note"><span>Exibindo: '+({destaque:'vagas em destaque',urgente:'vagas urgentes',confidencial:'vagas confidenciais'}[visibilityFilter])+'</span><button class="secondary" data-action="clear-visibility-filter">Desmarcar filtro</button></div>':'')+jobFilterFields(vs)+'<div id="job-results">'+expirationAlert(vs)+table(filtered.slice((pageNumber-1)*size,pageNumber*size),cs,true)+'<div class="pager"><span>'+filtered.length+' vagas • Página '+pageNumber+' de '+total+'</span><div class="row-actions"><button class="secondary" data-action="prev" '+(pageNumber<=1?'disabled':'')+'>Anterior</button><button class="secondary" data-action="next" '+(pageNumber>=total?'disabled':'')+'>Próxima</button></div></div></div></section>';}
  function plansView(e,vs) {var p=plan(e);return intro('Seu plano e recursos','Consulte a capacidade e a vigência da assinatura da sua empresa.','<button class="secondary" data-action="nav" data-view="overview">Voltar ao painel</button>')+'<section class="card plan-full">'+planStrip(e,vs)+'<h2>Recursos do seu plano</h2><div class="features">'+p.features.map(function(f){return '<div class="feature">'+icon('check')+esc(f)+'</div>';}).join('')+'</div><p class="note">A verificação da empresa depende da análise do cadastro. Consulte as condições dos planos para mais detalhes.</p><button class="secondary" data-action="all-plans" style="margin-top:20px">Conhecer outros planos</button></section>';}
