  function navigate(v,filter) {if(v==='publish'){openPublish();return;}if(v==='profile'){openProfile();return;}if(v==='candidates'){sessionStorage.removeItem('vagaCandidatosSelecionada');openCandidates();return;}var routes={verification:'verificacao-empresa',settings:'perfil-empresa',support:'contato'};if(routes[v]){invoke('irPara',[routes[v]]);return;}if(v==='exit'){if(typeof window.sairEmpresa==='function')window.sairEmpresa();else if(typeof window.logoutEmpresa==='function')window.logoutEmpresa();else{['empregaMaisPapel','empresaNome','empresaCnpj','empresaEmail','empregaMaisSupabaseAccessToken','empregaMaisSupabaseRefreshToken','empregaMaisEmpresaRemotaV49'].forEach(function(k){sessionStorage.removeItem(k);});invoke('irPara',['login-empresa']);}return;}view=v;visibilityFilter='';query='';statusFilter=filter||'all';pageNumber=1;render();window.scrollTo({top:0,behavior:'smooth'});}
